package v1beta1_test

import (
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	apiextensionsv1 "k8s.io/apiextensions-apiserver/pkg/apis/apiextensions/v1"
	celtest "k8s.io/apiextensions-apiserver/pkg/test"
)

const byoHostCRDPath = "../../../config/crd/bases/infrastructure.cluster.x-k8s.io_byohosts.yaml"

// newByoHostSpecValidator returns the CEL validator for the spec schema of the
// generated ByoHost CRD, so the test evaluates the rules the API server runs
// and fails if the generated CRD is stale.
func newByoHostSpecValidator(t *testing.T) celtest.CELValidateFunc {
	t.Helper()

	crd := celtest.MustLoadManifest[apiextensionsv1.CustomResourceDefinition](t, byoHostCRDPath)
	validatorsByVersion := celtest.FieldValidators(t, crd)

	validator, ok := validatorsByVersion["v1beta1"]["openAPIV3Schema.properties.spec"]
	require.True(t, ok, "ByoHost v1beta1 spec schema has no x-kubernetes-validations rules")
	return validator
}

func TestByoHostSpec_IdentityImmutable(t *testing.T) {
	t.Parallel()

	const (
		identity      = "byoh:host:default:worker-1-abc12"
		otherIdentity = "byoh:host:default:worker-1-xyz89"
		wantMessage   = "identity is immutable"
	)

	testCases := []struct {
		name    string
		oldSpec map[string]any
		newSpec map[string]any
		wantErr bool
	}{
		{
			name:    "same identity with another field changed is allowed",
			oldSpec: map[string]any{"identity": identity},
			newSpec: map[string]any{
				"identity":     identity,
				"desiredAgent": map[string]any{"version": "v1.2.3"},
			},
		},
		{
			name:    "changed identity is rejected",
			oldSpec: map[string]any{"identity": identity},
			newSpec: map[string]any{"identity": otherIdentity},
			wantErr: true,
		},
		{
			name:    "removed identity is rejected",
			oldSpec: map[string]any{"identity": identity},
			newSpec: map[string]any{},
			wantErr: true,
		},
		{
			name:    "identity set after create is rejected",
			oldSpec: map[string]any{},
			newSpec: map[string]any{"identity": identity},
			wantErr: true,
		},
		{
			name:    "no identity before or after with another field changed is allowed",
			oldSpec: map[string]any{},
			newSpec: map[string]any{
				"desiredAgent": map[string]any{"version": "v1.2.3"},
			},
		},
	}

	validate := newByoHostSpecValidator(t)

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()

			errs := validate(tc.newSpec, tc.oldSpec)

			if !tc.wantErr {
				assert.Empty(t, errs)
				return
			}
			require.Len(t, errs, 1)
			assert.Contains(t, errs[0].Error(), wantMessage)
		})
	}
}
